INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', 3, 'ದತ್ತಾಂಶ ಸೋರಿಕೆ ಎಂದರೇನು?', 'nan', 'nan', 'nan', 'nan', 'ತರಬೇತಿ ಸಮಯದಲ್ಲಿ ಸಂಬಂಧಿತ ಅಂಶ ಗೆ ಸಂಬಂಧಿತ ಅಂಶ ಅಥವಾ ಭವಿಷ್ಯ ಮಾಹಿತಿ ಅನಿರೀಕ್ಷಿತವಾಗಿ ಸಿಗುವ ಸ್ಥಿತಿ.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', 3, 'ಮಾದರಿ ಬದಲಾವಣೆ ಎಂದರೇನು?', 'nan', 'nan', 'nan', 'nan', 'ನಿಯೋಜನೆ ನಂತರ ಒಳಹರಿವು ದತ್ತಾಂಶ ಅಥವಾ ಒಳಹರಿವು-ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಬದಲಾಗುವುದರಿಂದ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಕುಸಿಯುವ ಸ್ಥಿತಿ.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', 3, 'ವಿವರಣೀಯ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಎಂದರೇನು?', 'nan', 'nan', 'nan', 'nan', 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ನ ಊಹೆಗಳು ಅಥವಾ ನಿರ್ಣಯಗಳು ಗೆ ಮಾನವರು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಬಹುದಾದ ವಿವರಣೆಗಳನ್ನು ಒದಗಿಸುವ ವಿಧಾನಗಳು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', 3, 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಪಕ್ಷಪಾತ ಎಂದರೇನು?', 'nan', 'nan', 'nan', 'nan', 'ದತ್ತಾಂಶ, ವಿನ್ಯಾಸ ಅಥವಾ ಸಂಬಂಧಿತ ಅಂಶ ನಲ್ಲಿನ ಸಂಬಂಧಿತ ಅಂಶ ಪಕ್ಷಪಾತ ಕಾರಣದಿಂದ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಕೆಲವು ಗುಂಪುಗಳಿಗೆ ಅನ್ಯಾಯವಾಗಿ ಪರಿಣಾಮ ಬೀರುವ ಸ್ಥಿತಿ.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', 3, 'ಮಾನವ-ಸಹಿತ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಎಂದರೇನು?', 'nan', 'nan', 'nan', 'nan', 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ನಲ್ಲಿ ಮಾನವ ಸಂಬಂಧಿತ ಅಂಶ, ಪ್ರತಿಕ್ರಿಯೆ ಅಥವಾ ನಿರ್ಣಯ ಕೈಗೊಳ್ಳುವಿಕೆ ಅನ್ನು ಒಳಗೊಂಡ ವಿಧಾನ.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆಯ ವ್ಯಾಖ್ಯಾನ, ಮುಖ್ಯ ಗುರಿಗಳು, ಉಪಕ್ಷೇತ್ರಗಳು ಮತ್ತು ದೈನಂದಿನ ಜೀವನದಲ್ಲಿನ ಅನ್ವಯಗಳನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಯ ಅರ್ಥ, ಸಂಬಂಧಿತ ಅಂಶ/ಸಂಬಂಧಿತ ಅಂಶ/ಸಂಬಂಧಿತ ಅಂಶ ಗುರಿಗಳು, ಯಂತ್ರ ಕಲಿಕೆ/ನೈಸರ್ಗಿಕ ಭಾಷಾ ಸಂಸ್ಕರಣೆ/ಗಣಕ ದೃಷ್ಟಿ/ಸಂಬಂಧಿತ ಅಂಶ ಮುಂತಾದ ಉಪಕ್ಷೇತ್ರಗಳು ಮತ್ತು ಆರೋಗ್ಯ ಸೇವೆ, ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಮುಂತಾದ ಅನ್ವಯಗಳನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಬುದ್ಧಿವಂತ ಕಾರ್ಯಕರ್ತ ನ ಪರಿಕಲ್ಪನೆಯನ್ನು ವಿವರಿಸಿ. ಕಾರ್ಯಕರ್ತ, ಪರಿಸರ, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಕ್ರಿಯೆ ಗಳ ನಡುವಿನ ಸಂಬಂಧವನ್ನು ಉದಾಹರಣೆಯೊಂದಿಗೆ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಕಾರ್ಯಕರ್ತ ಪರಿಸರವನ್ನು ಸಂಬಂಧಿತ ಅಂಶ ಮೂಲಕ ಗ್ರಹಿಸಿ ಕ್ರಿಯಾಕಾರಕಗಳು/ಕ್ರಿಯೆಗಳು ಮೂಲಕ ಪ್ರತಿಕ್ರಿಯಿಸುವ ರೀತಿ ಮತ್ತು ಅ ಮಾದರಿಯ ಬಳಕೆಯನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಮೇಲ್ವಿಚಾರಿತ, ಮೇಲ್ವಿಚಾರಣೆಯಿಲ್ಲದ ಮತ್ತು ಬಲವರ್ಧಿತ ಕಲಿಕೆ ಅನ್ನು ವ್ಯತ್ಯಾಸಗಳೊಂದಿಗೆ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಮೂರು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಗಳ ದತ್ತಾಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಪ್ರತಿಕ್ರಿಯೆ, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಉದಾಹರಣೆಗಳನ್ನು ಹೋಲಿಕೆ ಮಾಡಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಅಗಲ-ಮೊದಲ ಹುಡುಕಾಟ ಮತ್ತು ಆಳ-ಮೊದಲ ಹುಡುಕಾಟ ಸಂಬಂಧಿತ ಅಂಶ ಕ್ರಮಾವಳಿಗಳು ಅನ್ನು ಕ್ರಮಾವಳಿ ಆಧಾರಿತ ಸಂಬಂಧಿತ ಅಂಶ, ದತ್ತಾಂಶ ರಚನೆಸಂಬಂಧಿತ ಅಂಶ, ಪೂರ್ಣತೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಬಳಕೆಯ ದೃಷ್ಟಿಯಿಂದ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಅಗಲ-ಮೊದಲ ಹುಡುಕಾಟ ಸಂಬಂಧಿತ ಅಂಶ ಬಳಸುತ್ತದೆ; ಆಳ-ಮೊದಲ ಹುಡುಕಾಟ ಸಂಬಂಧಿತ ಅಂಶ/ಸಂಬಂಧಿತ ಅಂಶ ಬಳಸುತ್ತದೆ; ಸಂಬಂಧಿತ ಅಂಶ ಕ್ರಮ, ಪೂರ್ಣತೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಉತ್ತಮ ಮಾರ್ಗ ಹುಡುಕಾಟ ಸಂಬಂಧಿತ ಅಂಶ ಕ್ರಮಾವಳಿ ಅನ್ನು ವಿವರಿಸಿ ಮತ್ತು ಒಟ್ಟು ಅಂದಾಜು ವೆಚ್ಚ=ಈಗಿನ ಮಾರ್ಗದ ವೆಚ್ಚ+ಉಳಿದ ವೆಚ್ಚದ ಅಂದಾಜು ಎಂಬ ಸಂಬಂಧಿತ ಅಂಶ ನ ಪಾತ್ರವನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಮಾರ್ಗ ವೆಚ್ಚ ಈಗಿನ ಮಾರ್ಗದ ವೆಚ್ಚ, ಸಂಬಂಧಿತ ಅಂಶ ಉಳಿದ ವೆಚ್ಚದ ಅಂದಾಜು, ಸಂಬಂಧಿತ ಅಂಶ ಒಟ್ಟು ಅಂದಾಜು ವೆಚ್ಚ, ಸಂಬಂಧಿತ ಅಂಶ ಆಯ್ಕೆ ಮತ್ತು ಸ್ವೀಕಾರಾರ್ಹ ಸಂಬಂಧಿತ ಅಂಶ ಪರಿಕಲ್ಪನೆಗಳನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ತಜ್ಞ ವ್ಯವಸ್ಥೆ ನ ರಚನೆ ಅನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಜ್ಞಾನ ಭಂಡಾರ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಬಳಕೆದಾರ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಗ್ರಹಣೆ ಘಟಕಗಳನ್ನು ಚಿತ್ರ/ಸಂಬಂಧಿತ ಅಂಶ ಸಹಿತ ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', 10, 'ಅಸ್ಪಷ್ಟ ತರ್ಕ ನ ಮೂಲಭೂತ ಪರಿಕಲ್ಪನೆಗಳು ಮತ್ತು ಸ್ಪಷ್ಟ ದ್ವಿಮೌಲ್ಯ ಸಂಬಂಧಿತ ಅಂಶ ಗಿಂತ ಅದರ ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಅಸ್ಪಷ್ಟ ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಚರಗಳು, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಪ್ರಮಾಣ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ಉದಾಹರಣೆಯೊಂದಿಗೆ ವಿವರಿಸಬೇಕು.', 'nan');
