INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', 10, 'ವರ್ಗೀಕರಣ ಸಂಬಂಧಿತ ಅಂಶ ಅಳತೆಗಳು ಗಳಾದ ಸರಿತನ, ಸಂಬಂಧಿತ ಅಂಶ, ಎಲ್ಲಾ ಮತ್ತು ಸಮತೋಲನ ಅಳತೆ ಅನ್ನು ಸೂತ್ರಗಳೊಂದಿಗೆ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ನಿಜವಾದ ಧನಾತ್ಮಕ, ನಿಜವಾದ ಋಣಾತ್ಮಕ, ತಪ್ಪು ಧನಾತ್ಮಕ, ತಪ್ಪು ಋಣಾತ್ಮಕ ಆಧಾರಿತ ಸೂತ್ರಗಳು ಮತ್ತು ಯಾವ ಸಂದರ್ಭಗಳಲ್ಲಿ ಯಾವ ಸಂಬಂಧಿತ ಅಂಶ ಮುಖ್ಯ ಎಂಬುದನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
