INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', 10, 'ದತ್ತಾಂಶ ಪೂರ್ವಸಿದ್ಧತೆ ನ ಪ್ರಮುಖ ಹಂತಗಳನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಕಾಣೆಯಾದ ಮೌಲ್ಯಗಳು, ಸಂಬಂಧಿತ ಅಂಶ, ಅಸಾಮಾನ್ಯ ಮೌಲ್ಯ, ಸಂಕೇತ ಪರಿವರ್ತನೆ, ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', 10, 'ಲಕ್ಷಣ ನಿರ್ಮಾಣ ಎಂದರೇನು? ಒಂದು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ನಲ್ಲಿ ಉತ್ತಮ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಗೆ ಹೇಗೆ ಸಹಾಯ ಮಾಡುತ್ತವೆ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಕ್ಷೇತ್ರ ಸಂಬಂಧಿತ ಅಂಶ ಬಳಸಿ ಸಂಬಂಧಿತ ಅಂಶ ಚರಗಳು ಅನ್ನು ಸಂಬಂಧಿತ ಅಂಶ ಪ್ರತಿನಿಧಿತ್ವ ಆಗಿ ಪರಿವರ್ತಿಸುವ ವಿಧಾನ ಮತ್ತು ಉದಾಹರಣೆಗಳನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', 10, 'ಸಂಕುಚನಾತ್ಮಕ ನರಜಾಲ ರಚನೆ ಅನ್ನು ಸಂಕುಚನ ಕಾರ್ಯ, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಪರ್ಕಿತ ಸಂಬಂಧಿತ ಅಂಶ ಮೂಲಕ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಶೋಧಕಗಳು, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ವರ್ಗೀಕರಣ ಸಂಬಂಧಿತ ಅಂಶ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', 10, 'ನೈಸರ್ಗಿಕ ಭಾಷಾ ಸಂಸ್ಕರಣೆ ಕಾರ್ಯಪ್ರವಾಹ ಅನ್ನು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಗ್ರಹಣೆ ನಿಂದ ಊಹೆ ವರೆಗೆ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಶುದ್ಧೀಕರಣ, ರೂಪ ಸಾಮಾನ್ಯೀಕರಣ, ಸಂಬಂಧಿತ ಅಂಶ, ಪ್ರತಿನಿಧಿತ್ವ/ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
