INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ದತ್ತಾಂಶ ಸೋರಿಕೆ ಎಂದರೇನು? ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ನಲ್ಲಿ ಸಂಬಂಧಿತ ಅಂಶ ಹೇಗೆ ಉಂಟಾಗುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಹೇಗೆ ತಪ್ಪಿಸಬಹುದು?', 'nan', 'nan', 'nan', 'nan', 'ತರಬೇತಿ-ಪರೀಕ್ಷೆ ಸಂಬಂಧಿತ ಅಂಶ, ಪೂರ್ವಸಿದ್ಧತೆ ಹೊಂದಾಣಿಕೆ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಉದಾಹರಣೆಗಳೊಂದಿಗೆ ಸಂಬಂಧಿತ ಅಂಶ ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಮಾದರಿ ಬದಲಾವಣೆ ಮತ್ತು ಇ ಬದಲಾವಣೆ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಒಳಹರಿವು ಸಂಬಂಧಿತ ಅಂಶ ಬದಲಾವಣೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ/ಸಂಬಂಧಿತ ಅಂಶ ಪರಿಕಲ್ಪನೆ ಬದಲಾವಣೆ ಗಳ ವ್ಯತ್ಯಾಸ, ಮೇಲ್ವಿಚಾರಣೆ ಮತ್ತು ತರಬೇತಿ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ವಿವರಣೀಯ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಯ ಅಗತ್ಯವನ್ನು ವಿವರಿಸಿ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ವಿವರಣೆಸಂಬಂಧಿತ ಅಂಶ ಗೆ ಕೆಲವು ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ವಿವರಣೀಯತೆ, ಸಂಬಂಧಿತ ಅಂಶ ಪ್ರಾಮುಖ್ಯತೆ, ಸ್ಥಳೀಯ ವಿವರಣೆಸಂಬಂಧಿತ ಅಂಶ, ಸಮಗ್ರ ವಿವರಣೆಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ಯಲ್ಲಿ ವಿರೋಧಾತ್ಮಕ ದಾಳಿಗಳು ಮತ್ತು ದತ್ತಾಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ದಾಳಿ ಸಂಬಂಧಿತ ಅಂಶ, ವಿರೋಧಾತ್ಮಕ ಒಳಹರಿವುಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ತರಬೇತಿ ದತ್ತಾಂಶ, ಪತ್ತೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಕ್ರಮಗಳನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಶಿಫಾರಸು ವ್ಯವಸ್ಥೆ ನ ಸಹಯೋಗಾತ್ಮಕ ಶೋಧಕ ಮತ್ತು ವಿಷಯ ಗುಣಲಕ್ಷಣ ಆಧಾರಿತ ಶೋಧಕ ಅನ್ನು ಹೋಲಿಸಿ ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಬಳಕೆದಾರ-ವಸ್ತು ಕ್ರಿಯೆಗಳು, ವಸ್ತು ಸಂಬಂಧಿತ ಅಂಶ, ಸಾಮ್ಯತೆ ಮತ್ತು ಹೊಸ ಬಳಕೆದಾರ ಅಥವಾ ಹೊಸ ವಸ್ತು ಸಮಸ್ಯೆ ಸಮಸ್ಯೆಯನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಗಣಕ ದೃಷ್ಟಿ ನಲ್ಲಿ ಸಂಬಂಧಿತ ಅಂಶ ಪತ್ತೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ವರ್ಗೀಕರಣ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನು ವಿವರಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ವರ್ಗೀಕರಣ ಸಂಬಂಧಿತ ಅಂಶ-ಸಂಬಂಧಿತ ಅಂಶ ಗುರುತು ನೀಡುತ್ತದೆ; ಪತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ವರ್ಗಗಳು ಮತ್ತು ವಿಶ್ವಾಸ ನೀಡುತ್ತದೆ ಎಂಬುದನ್ನು ಉದಾಹರಣೆಯೊಂದಿಗೆ ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ಗಾಗಿ ಉತ್ತಮ ದತ್ತಾಂಶ ಸಮೂಹ ಹೇಗೆ ಸಿದ್ಧಪಡಿಸಬೇಕು?', 'nan', 'nan', 'nan', 'nan', 'ಸಮಸ್ಯೆ ವ್ಯಾಖ್ಯಾನ, ದತ್ತಾಂಶ ಸಂಗ್ರಹಣೆ, ಗುರುತುಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ ಪರಿಶೀಲನೆಗಳು, ಪ್ರತಿನಿಧಿತ್ವ, ಸಂಬಂಧಿತ ಅಂಶ, ಗೌಪ್ಯತೆ ಮತ್ತು ಸಂಬಂಧಿತ ಅಂಶ ಹಂತಗಳನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಮಾನವ-ಸಹಿತ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ರಚನೆ ಅನ್ನು ವಿವರಿಸಿ ಮತ್ತು ಯಾವ ಸಂದರ್ಭಗಳಲ್ಲಿ ಮಾನವ ಸಂಬಂಧಿತ ಅಂಶ ಅಗತ್ಯವಾಗಬಹುದು ಎಂಬುದನ್ನು ಚರ್ಚಿಸಿ.', 'nan', 'nan', 'nan', 'nan', 'ಹೆಚ್ಚಿನ ಅಪಾಯದ ನಿರ್ಣಯಗಳು, ಸಂಬಂಧಿತ ಅಂಶ ಊಹೆಗಳು, ಸಂಬಂಧಿತ ಅಂಶ ನಿರ್ವಹಣೆ, ಪ್ರತಿಕ್ರಿಯೆ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಲೆಕ್ಕಪರಿಶೀಲನಾ ಸಾಮರ್ಥ್ಯ ಕುರಿತು ವಿವರಿಸಬೇಕು.', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಬಹು ಆಯ್ಕೆ', 'ಕಠಿಣ', 2, 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ವ್ಯವಸ್ಥೆಯ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಸಂಬಂಧಿತ ಅಂಶ ನಲ್ಲಿ ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು ಯಾವ ಅಂಶಗಳನ್ನು ಗಮನಿಸಬಹುದು?', 'ಊಹೆ ಸಂಬಂಧಿತ ಅಂಶ', 'ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯ', 'ದತ್ತಾಂಶ ಸಂಬಂಧಿತ ಅಂಶ', 'ಸಂಪನ್ಮೂಲ ಸಂಬಂಧಿತ ಅಂಶ', 'ಅ,ಆ,ಇ,ಈ', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ಸರಿ ಅಥವಾ ತಪ್ಪು', 'ಕಠಿಣ', 1, 'ನೈಜ ಬಳಕೆ ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ನಿಯೋಜಿಸುವುದು ಮಾಡಿದ ನಂತರವೂ ಅದರ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ದತ್ತಾಂಶ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ನಿರಂತರವಾಗಿ ಗಮನಿಸುವುದು ಉಪಯುಕ್ತವಾಗಿದೆ.', 'ಸರಿ', 'ತಪ್ಪು', 'nan', 'nan', 'ಸರಿ', 'nan');
INSERT INTO ಪ್ರಶ್ನಾ_ಭಂಡಾರ (`ವಿಷಯ`, `ಭಾಷೆ`, `ಪ್ರಶ್ನೆಯ ವಿಧ`, `ಕಠಿಣತೆ`, `ಅಂಕಗಳು`, `ಪ್ರಶ್ನೆ`, `ಆಯ್ಕೆ ಅ`, `ಆಯ್ಕೆ ಆ`, `ಆಯ್ಕೆ ಇ`, `ಆಯ್ಕೆ ಈ`, `ಸರಿಯಾದ ಉತ್ತರ`, `ವಿವರಣೆ`) VALUES ('ಅ-ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', 10, 'ಒಂದು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಆಧಾರಿತ ಪರೀಕ್ಷಾ ವ್ಯವಸ್ಥೆಯಲ್ಲಿ ಪ್ರಶ್ನೆ ಶಿಫಾರಸು, ಸ್ವಯಂಚಾಲಿತ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ಬಳಸುವಾಗ ದತ್ತಾಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಸಂಬಂಧಿತ ಅಂಶ, ಗೌಪ್ಯತೆ ಮತ್ತು ಮಾನವ ಸಂಬಂಧಿತ ಅಂಶ ಅನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸಬಹುದು?', 'nan', 'nan', 'nan', 'nan', 'ಪ್ರಶ್ನೆ ಸಂಬಂಧಿತ ಅಂಶ ಪರಿಶೀಲನೆ, ಸಂಬಂಧಿತ ಅಂಶ ಸರಿತನ ಪರಿಶೀಲನೆಗಳು, ಸಂಬಂಧಿತ ಅಂಶ ದತ್ತಾಂಶ, ಗೌಪ್ಯತೆ ನಿಯಂತ್ರಣಗಳು, ಅನುಮತಿ, ಸಂಬಂಧಿತ ಅಂಶ ಸಂಬಂಧಿತ ಅಂಶ, ಪಕ್ಷಪಾತ ಪರೀಕ್ಷೆ, ವಿವರಣೀಯತೆ, ಮಾನವ ಸಂಬಂಧಿತ ಅಂಶ, ಲೆಕ್ಕಪರಿಶೀಲನೆ ಸಂಬಂಧಿತ ಅಂಶ ಮತ್ತು ನಿರಂತರ ಮೇಲ್ವಿಚಾರಣೆ ಒಳಗೊಂಡ ಸಮಗ್ರ ವಿಧಾನವನ್ನು ವಿವರಿಸಬೇಕು.', 'nan');
